// Human-facing progress output. init --json redirects this to stderr so stdout
// stays machine-readable.
// Shared, reassignable output state (an object, so every module sees changes).
export const io = {
  emit: (message) => console.log(message),
  detailSink: null,
};
export function log(message) {
  io.emit(message);
}

// File-by-file progress ("Created CLAUDE.md") is for developers. `init` collects
// it here and prints a plain summary instead; --verbose shows the list.
export function detail(message) {
  if (io.detailSink) io.detailSink.push(String(message).trim());
  else log(message);
}

// Which Piezas this computer talks to: production, unless someone signed in
// with `piezas login --staging`, which saves the choice next to the sign-in
// (target.json in the Piezas home folder). PIEZAS_TARGET overrides it, and
// flags and PIEZAS_* addresses still win over these defaults. Every build is
// the same; nothing environment-specific is baked in.


export function saveTarget(target, env = process.env) {
  const file = join(piezasHomeDir(env), 'target.json');
  if (target === 'production') {
    rmSync(file, { force: true });
    return;
  }
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, `${JSON.stringify({ target }, null, 2)}\n`);
}


