// Flags that never take a value — they must not swallow a following
// positional (e.g. `piezas init --wait mydir` targets mydir/).
export const BOOLEAN_FLAGS = new Set([
  'delete',
  'fromLogin',
  'allowEmpty',
  'context',
  'isolated',
  'json',
  'mcp',
  'mixed',
  'noDeps',
  'skipDeps',
  'skipInstall',
  'status',
  'strict',
  'verbose',
  'wait',
  'yes',
]);

export function parseCliArgs(args) {
  const flags = {};
  const positional = [];

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (!arg.startsWith('--')) {
      positional.push(arg);
      continue;
    }

    const [rawKey, inlineValue] = arg.slice(2).split('=');
    const key = rawKey.replace(/-([a-z])/g, (_, char) => char.toUpperCase());
    if (inlineValue !== undefined) {
      flags[key] = appendFlagValue(flags[key], inlineValue);
    } else if (!BOOLEAN_FLAGS.has(key) && args[i + 1] && !args[i + 1].startsWith('--')) {
      flags[key] = appendFlagValue(flags[key], args[i + 1]);
      i += 1;
    } else {
      flags[key] = appendFlagValue(flags[key], true);
    }
  }

  return { flags, positional };
}

export function appendFlagValue(existing, value) {
  if (existing === undefined) return value;
  return Array.isArray(existing) ? [...existing, value] : [existing, value];
}

// spliceMarkerBlock replaces the START..END block inside `existing` with the
// block from `content`, preserving any user content around the markers. Falls
// back to a full replace when the block cannot be located on both sides.
export function spliceMarkerBlock(existing, content, startMarker, endMarker) {
  if (!endMarker) return content;
  const start = existing.indexOf(startMarker);
  const end = existing.indexOf(endMarker, start);
  const newStart = content.indexOf(startMarker);
  const newEnd = content.indexOf(endMarker, newStart);
  if (start < 0 || end < 0 || newStart < 0 || newEnd < 0) return content;
  return (
    existing.slice(0, start) +
    content.slice(newStart, newEnd + endMarker.length) +
    existing.slice(end + endMarker.length)
  );
}

// A tool's config folder can be write-protected by the agent that is running
// init (Codex's sandbox protects .codex/). One unwritable integration file must
// not abort setup: skip it, say so, carry on.
export const PROTECTED_FS_CODES = new Set(['EPERM', 'EACCES', 'EROFS']);

export function safeMkdir(dir) {
  try {
    mkdirSync(dir, { recursive: true });
    return true;
  } catch (error) {
    if (PROTECTED_FS_CODES.has(error?.code)) return false;
    throw error;
  }
}

export function writeIfNew(filePath, content, label, options = {}) {
  try {
    return writeIfNewUnsafe(filePath, content, label, options);
  } catch (error) {
    if (PROTECTED_FS_CODES.has(error?.code)) {
      log(`  Skipped ${label} (that folder is protected in this environment)`);
      return;
    }
    throw error;
  }
}

export function writeIfNewUnsafe(filePath, content, label, options = {}) {
  if (!safeMkdir(dirname(filePath))) {
    log(`  Skipped ${label} (that folder is protected in this environment)`);
    return;
  }
  const startMarker = options.startMarker || PIEZAS_CONTEXT_START;
  const endMarker = options.endMarker ?? (startMarker === PIEZAS_CONTEXT_START ? PIEZAS_CONTEXT_END : undefined);
  const appendIfNoMarker = options.appendIfNoMarker ?? true;

  if (existsSync(filePath)) {
    const existing = readFileSync(filePath, 'utf-8');
    if (existing === content) {
      detail(`  ${label} is up to date - skipping`);
      return;
    }
    if (existing.includes(startMarker)) {
      const updated = spliceMarkerBlock(existing, content, startMarker, endMarker);
      if (updated === existing) {
        detail(`  ${label} is up to date - skipping`);
        return;
      }
      writeFileSync(filePath, updated);
      detail(`  Updated ${label}`);
      return;
    }
    if (!appendIfNoMarker) {
      detail(`  ${label} exists - skipping`);
      return;
    }
    writeFileSync(filePath, `${existing.trimEnd()}\n\n${content}`);
    detail(`  Updated ${label}`);
  } else {
    writeFileSync(filePath, content);
    detail(`  Created ${label}`);
  }
}

export function writeFileIfMissing(filePath, content, label) {
  if (existsSync(filePath)) {
    const existing = readFileSync(filePath, 'utf-8');
    if (existing === content) {
      detail(`  ${label} is up to date - skipping`);
    } else {
      detail(`  ${label} exists - skipping`);
    }
    return false;
  }

  mkdirSync(dirname(filePath), { recursive: true });
  writeFileSync(filePath, content);
  detail(`  Created ${label}`);
  return true;
}

// upsertManifest creates piezas.manifest.json when missing, or extends an
// existing one with app metadata (appName, apiBaseUrl) without touching any
// other field the project may have customized.
export function upsertManifest(manifestPath, buildOptions) {
  if (!existsSync(manifestPath)) {
    const manifest = buildDefaultManifest(buildOptions);
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
    detail('  Created piezas.manifest.json');
    return manifest;
  }

  let manifest;
  try {
    manifest = readJsonFile(manifestPath);
  } catch {
    log('  piezas.manifest.json is not valid JSON - leaving it untouched');
    return null;
  }

  let changed = false;
  if (buildOptions.appName && manifest.appName !== buildOptions.appName) {
    manifest.appName = buildOptions.appName;
    changed = true;
  }
  if (manifest.appName === undefined) {
    manifest.appName = null;
    changed = true;
  }
  if (manifest.apiBaseUrl === undefined) {
    manifest.apiBaseUrl = DEFAULT_API_BASE_URL;
    changed = true;
  }
  // The contract stamp records which version this project adopted and WHEN.
  // The fetch timestamp moves only when the VERSION changes — re-running init
  // against the same served version re-fetches but adopts nothing new, so the
  // manifest stays byte-stable (init is idempotent on an unchanged contract).
  const contractVersion = buildOptions.contractVersion ?? null;
  const contractFetchedAt = buildOptions.contractFetchedAt ?? null;
  if (manifest.contractVersion !== contractVersion) {
    manifest.contractVersion = contractVersion;
    manifest.contractFetchedAt = contractFetchedAt;
    changed = true;
  } else if (manifest.contractFetchedAt === undefined) {
    // Legacy manifest recorded a version but never a fetch time — backfill it.
    manifest.contractFetchedAt = contractFetchedAt;
    changed = true;
  }

  if (changed) {
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
    detail('  Updated piezas.manifest.json (app metadata)');
  } else {
    log('  piezas.manifest.json is up to date - skipping');
  }
  return manifest;
}

export function mcpRouteContent() {
  return `import { piezasMcp } from '@piezas/sdk';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const handler = piezasMcp({
  entitiesUrl: process.env.PIEZAS_ENTITIES_URL || 'https://api.piezas.ai/entities',
  pipelineUrl: process.env.PIEZAS_PIPELINE_URL || 'https://api.piezas.ai/pipeline',
  tasksUrl: process.env.PIEZAS_TASKS_URL || 'https://api.piezas.ai/tasks',
  name: process.env.MCP_SERVER_NAME || 'piezas-app',
});

function requireMcpAccess(req: Request) {
  const hasAppSession = Boolean(req.headers.get('authorization') || req.headers.get('cookie'));
  const hasTenantContext = Boolean(req.headers.get('x-tenant-id') && req.headers.get('x-user-id'));
  if (hasAppSession && hasTenantContext) return null;

  return Response.json(
    { error: 'MCP route requires app auth plus X-Tenant-Id and X-User-Id.' },
    { status: 401 },
  );
}

export async function POST(req: Request) {
  // Replace this guard with your app session/auth check before exposing MCP publicly.
  const denied = requireMcpAccess(req);
  if (denied) return denied;

  return handler(req);
}
`;
}

export function scaffoldMcpRoute(projectDir, deploymentMode, requested) {
  if (!requested) {
    return { enabled: false, routePath: null };
  }

  if (!supportsMcpRoute(deploymentMode)) {
    if (deploymentMode === 'static') {
      log('  Skipped MCP route: static deployment mode cannot host server routes.');
    } else {
      log('  Skipped MCP route: mount `piezasMcp` in your server framework for this deployment mode.');
    }
    return {
      enabled: false,
      routePath: null,
      skippedReason: deploymentMode === 'static' ? 'static-deployment-mode' : 'manual-server-framework',
    };
  }

  writeFileIfMissing(
    resolve(projectDir, MCP_ROUTE_PATH),
    mcpRouteContent(),
    MCP_ROUTE_PATH,
  );
  return { enabled: true, routePath: MCP_ROUTE_PATH };
}

// --- the scenario test harness --------------------------------------------
//
// The protocol's BUILD gate is "one test per S-nnn, suite green".
// That is only cheap if the harness is already
// there: a config, a smoke test, a place for the scenario files, and a seed
// stub. Everything here is written ONLY when absent — a project's own harness
// is never touched.

export const PLAYWRIGHT_TEST_VERSION = '^1.47.0';
export const HARNESS_FILES = {
  config: 'playwright.config.ts',
  smoke: 'tests/smoke.spec.ts',
  scenarios: 'tests/scenarios/README.md',
  seed: 'scripts/seed.ts',
};

export function playwrightConfigContent() {
  return `import { defineConfig, devices } from '@playwright/test';

// The Piezas scenario harness. \`npx piezas test\` runs this suite and writes
// .piezas/test-attestation.json — the evidence \`npx piezas deploy\` reports.
// PW_BASE_URL points the SAME suite at local dev, a preview, or the deployed
// app, so nothing about a test changes when the target does.
export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  forbidOnly: Boolean(process.env.CI),
  retries: process.env.CI ? 1 : 0,
  reporter: 'list',
  use: {
    baseURL: process.env.PW_BASE_URL || 'http://localhost:3000',
    trace: 'on-first-retry',
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
});
`;
}

export function smokeTestContent() {
  return `import { expect, test } from '@playwright/test';

// The one test every app has. A red smoke test means nothing below it is worth
// reading: the page either renders or it does not.
test('the home page renders with a clean console', async ({ page }) => {
  const errors: string[] = [];
  page.on('console', (message) => {
    if (message.type() === 'error') errors.push(message.text());
  });
  page.on('pageerror', (error) => errors.push(error.message));

  const response = await page.goto('/');

  expect(response?.ok(), \`GET / returned \${response?.status()}\`).toBeTruthy();
  await expect(page.locator('body')).not.toBeEmpty();
  expect(errors, \`console errors on /:\\n\${errors.join('\\n')}\`).toEqual([]);
});
`;
}

export function scenariosReadmeContent() {
  return `# Acceptance scenarios

One file per acceptance scenario in \`SPEC.md\`, named for the scenario it
proves: \`S-001.spec.ts\` tests \`### S-001\`, and nothing else. Write each file
from the scenario's own Given/When/Then — the Given is the fixture setup (see
\`scripts/seed.ts\`), the When is the interaction, the Then is the assertion —
and keep the scenario title in the test name so a red run names the requirement
that broke. \`npx piezas spec coverage\` fails until every \`S-nnn\` in the spec
has a file here, and \`npx piezas test\` records how many of them ran.

**Select by \`data-testid\`.** Text and CSS selectors break on the next redesign
and turn a passing suite into a maintenance tax; a test id survives copy
changes, restyling and layout moves. Add \`data-testid\` to the elements a
scenario drives, name it for the thing (\`data-testid="cancel-booking"\`), and
select it with \`page.getByTestId('cancel-booking')\`. \`npx piezas doctor\`
counts the interactive elements that still have none (PZ026).
`;
}

export function seedScriptContent() {
  return `// Seed the fixture data the scenario tests assume, through @piezas/sdk — the
// same services the app itself calls, so a test that passes here exercises the
// real substrate rather than a mock of it.
//
// Two rules make a suite trustworthy:
//   1. Deterministic — fixed ids and fixed dates, so the same run gives the
//      same result today and in March.
//   2. Re-runnable — clean up or upsert; a second run must not double the data.
//
// Point it at a TEST app's key, never a live one:
//   PIEZAS_API_KEY=<test key> npx tsx scripts/seed.ts

import { createPiezasClient } from '@piezas/sdk';

const client = createPiezasClient({
  apiKey: process.env.PIEZAS_API_KEY,
  baseUrl: process.env.PIEZAS_API_URL,
});

export async function seed() {
  // TODO(you): create the fixtures your S-nnn scenarios say "Given ...".
  // Example:
  // await client.records.upsert('bookings', { id: 'seed-booking-1', startTime: '2026-01-05T19:00:00Z' });
  return client;
}

if (process.argv[1]?.endsWith('seed.ts')) {
  seed().then(() => console.log('seeded'));
}
`;
}

// ensurePlaywrightDependency declares the harness's ONLY dependency. An
// existing pin is never touched — the project's choice outranks ours.
export function ensurePlaywrightDependency(projectDir) {
  const packagePath = resolve(projectDir, 'package.json');
  let pkg;
  try {
    pkg = readJsonFile(packagePath);
  } catch {
    return false;
  }
  if (pkg.dependencies?.['@playwright/test'] || pkg.devDependencies?.['@playwright/test']) return false;
  pkg.devDependencies = { ...(pkg.devDependencies || {}), '@playwright/test': PLAYWRIGHT_TEST_VERSION };
  writeFileSync(packagePath, `${JSON.stringify(pkg, null, 2)}\n`);
  detail(`  Added @playwright/test ${PLAYWRIGHT_TEST_VERSION} to devDependencies`);
  return true;
}

export function scaffoldTestHarness(projectDir) {
  const created = [];
  const files = [
    [HARNESS_FILES.config, playwrightConfigContent()],
    [HARNESS_FILES.smoke, smokeTestContent()],
    [HARNESS_FILES.scenarios, scenariosReadmeContent()],
    [HARNESS_FILES.seed, seedScriptContent()],
  ];
  for (const [rel, content] of files) {
    if (writeFileIfMissing(resolve(projectDir, rel), content, rel)) created.push(rel);
  }
  const dependencyAdded = ensurePlaywrightDependency(projectDir);
  if (created.length > 0 || dependencyAdded) {
    detail('  Scenario harness ready — install it once with: npm install && npx playwright install');
  }
  return { created, dependencyAdded };
}

export function packageNameFromDir(projectDir) {
  const name = basename(projectDir)
    .toLowerCase()
    .replace(/^@/, '')
    .replace(/[^a-z0-9._-]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return name || 'piezas-app';
}

export function ensurePackageJson(projectDir) {
  const pkgJsonPath = resolve(projectDir, 'package.json');
  if (existsSync(pkgJsonPath)) {
    return;
  }

  const pkg = {
    name: packageNameFromDir(projectDir),
    version: '0.1.0',
    private: true,
    type: 'module',
  };

  writeFileSync(pkgJsonPath, `${JSON.stringify(pkg, null, 2)}\n`);
  detail('  Created package.json');
}

export function stripQuotes(value) {
  const match = /^(['"])(.*)\1$/.exec(value);
  return match ? match[2] : value;
}

// readEnvKeyValue returns the PIEZAS_API_KEY value from a dotenv-style file,
// or undefined when the file or the line is absent.
export function readEnvKeyValue(filePath) {
  if (!existsSync(filePath)) return undefined;
  for (const line of readFileSync(filePath, 'utf-8').split(/\r?\n/)) {
    const match = ENV_KEY_LINE.exec(line);
    if (match) return stripQuotes(match[1].trim());
  }
  return undefined;
}

// writeEnvKey merges PIEZAS_API_KEY=<key> into the project .env: creates the
// file, appends the line, or replaces ONLY the existing PIEZAS_API_KEY line.
// Every other byte — including CRLF/LF line endings — is preserved.
export function writeEnvKey(envPath, key) {
  if (!existsSync(envPath)) {
    writeFileSync(envPath, `PIEZAS_API_KEY=${key}\n`);
    return 'created';
  }

  const content = readFileSync(envPath, 'utf-8');
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const parts = content.split(/(\r?\n)/);
  for (let i = 0; i < parts.length; i += 2) {
    const match = ENV_KEY_LINE.exec(parts[i]);
    if (!match) continue;
    if (stripQuotes(match[1].trim()) === key) return 'kept';
    parts[i] = `PIEZAS_API_KEY=${key}`;
    writeFileSync(envPath, parts.join(''));
    return 'replaced';
  }

  const needsNewline = content.length > 0 && !content.endsWith('\n');
  writeFileSync(envPath, `${content}${needsNewline ? eol : ''}PIEZAS_API_KEY=${key}${eol}`);
  return 'appended';
}

// writeEnvVar merges NAME=<value> into .env with the same preservation
// semantics as writeEnvKey (create / append / replace only that line).
export function writeEnvVar(envPath, name, value) {
  const lineRe = new RegExp(`^\\s*(?:export\\s+)?${name}\\s*=\\s*(.*)$`);
  if (!existsSync(envPath)) {
    writeFileSync(envPath, `${name}=${value}\n`);
    return 'created';
  }
  const content = readFileSync(envPath, 'utf-8');
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const parts = content.split(/(\r?\n)/);
  for (let i = 0; i < parts.length; i += 2) {
    const match = lineRe.exec(parts[i]);
    if (!match) continue;
    if (stripQuotes(match[1].trim()) === value) return 'kept';
    parts[i] = `${name}=${value}`;
    writeFileSync(envPath, parts.join(''));
    return 'replaced';
  }
  const needsNewline = content.length > 0 && !content.endsWith('\n');
  writeFileSync(envPath, `${content}${needsNewline ? eol : ''}${name}=${value}${eol}`);
  return 'appended';
}

export const GITIGNORE_ENV_PATTERNS = new Set(['.env', '/.env', '.env*', '*.env', '**/.env']);

// ensureGitignore makes sure .env is git-ignored. Respects existing patterns
// (.env, .env*, *.env, ...) and appends a "# piezas" section only when needed.
export function ensureGitignore(projectDir) {
  const gitignorePath = resolve(projectDir, '.gitignore');
  if (!existsSync(gitignorePath)) {
    writeFileSync(gitignorePath, '# piezas\n.env\n');
    detail('  Created .gitignore (.env ignored)');
    return true;
  }

  const content = readFileSync(gitignorePath, 'utf-8');
  const covered = content
    .split(/\r?\n/)
    .some((line) => GITIGNORE_ENV_PATTERNS.has(line.trim()));
  if (covered) {
    return false;
  }

  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  let updated = content;
  if (updated.length > 0 && !updated.endsWith('\n')) updated += eol;
  if (updated.length > 0) updated += eol;
  updated += `# piezas${eol}.env${eol}`;
  writeFileSync(gitignorePath, updated);
  detail('  Updated .gitignore (.env ignored)');
  return true;
}

export function promptViaTerminal(question) {
  return new Promise((resolvePrompt) => {
    const rl = createInterface({ input: process.stdin, output: process.stdout });
    rl.question(question, (answer) => {
      rl.close();
      resolvePrompt(answer);
    });
  });
}

// waitForEnvKey polls the project dir for a dropped-in .env (or the names a
// browser may give the dashboard download) containing PIEZAS_API_KEY.
export async function waitForEnvKey(projectDir, timeoutSeconds, intervalMs) {
  log(`  Waiting for your API key: drop a ${WAIT_FILE_CANDIDATES.join(' or ')} file`);
  log(`  containing PIEZAS_API_KEY into ${projectDir}`);
  log(`  (dashboard -> API Keys -> "Download .env"). Checking every ${Math.round(intervalMs / 100) / 10}s, timeout ${timeoutSeconds}s.`);

  const deadline = Date.now() + timeoutSeconds * 1000;
  for (;;) {
    for (const name of WAIT_FILE_CANDIDATES) {
      const value = readEnvKeyValue(resolve(projectDir, name));
      if (value) {
        log(`  Found PIEZAS_API_KEY in ${name}`);
        return { value, file: name };
      }
    }
    if (Date.now() >= deadline) {
      log(`  No key file appeared within ${timeoutSeconds}s - continuing without a key.`);
      return undefined;
    }
    await new Promise((resolveDelay) => setTimeout(resolveDelay, intervalMs));
  }
}

// resolveApiKey implements the key-intake precedence:
// existing .env key > --key flag > process env > `piezas login` auto-mint >
// interactive paste prompt > --wait.
// Only explicitly provided keys (--key/prompt/wait) may replace an existing
// .env value; the process env never overrides an already-configured project.
export async function resolveApiKey(envPath, projectDir, options) {
  const existingValue = readEnvKeyValue(envPath);
  const flagKey = typeof options.key === 'string' && options.key.trim() ? options.key.trim() : undefined;

  if (existingValue && !flagKey) {
    return { key: existingValue, source: 'env-file' };
  }
  if (flagKey) {
    return { key: flagKey, source: 'flag' };
  }

  const processKey = (options.env ?? process.env).PIEZAS_API_KEY;
  if (processKey) {
    return { key: processKey, source: 'process-env' };
  }

  // Signed in via `piezas login`? Create the app and mint its key right here,
  // from the terminal -- no dashboard visit, no copy-paste. This runs BEFORE the
  // manual paste prompt so a logged-in user is never sent to the web UI to fetch
  // a key by hand. Declining the offer falls through to the manual paths below.
  const minted = await resolveKeyViaLogin(projectDir, options);
  if (minted) {
    return minted;
  }

  if (options.interactive && !options.yes) {
    const promptFn = options.promptFn ?? promptViaTerminal;
    const answer = String((await promptFn(KEY_PROMPT)) ?? '').trim();
    if (answer) {
      return { key: answer, source: 'prompt' };
    }
  }

  if (options.wait) {
    const timeoutSeconds = options.waitTimeout ?? DEFAULT_WAIT_TIMEOUT_SECONDS;
    const intervalMs = options.waitIntervalMs ?? DEFAULT_WAIT_INTERVAL_MS;
    const found = await waitForEnvKey(projectDir, timeoutSeconds, intervalMs);
    if (found) {
      return { key: found.value, source: 'wait', sourceFile: found.file };
    }
  }

  return { key: undefined, source: 'none' };
}

